/**
 * Bulk issue imports: the per-org import-key ledger and the single transaction
 * that writes a whole batch (new labels, issues, label links, ledger row).
 */
import { and, eq, inArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, toIssue } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

export interface IssueImportRecord {
  readonly orgId: OrgId;
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

/** One row with its assignee already resolved; labels are still names. */
export interface PreparedImportRow {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly labelNames: readonly string[];
  readonly dueAt: IsoTimestamp | null;
}

export type ImportWriteResult =
  | { readonly replayed: true; readonly record: IssueImportRecord }
  | {
      readonly replayed: false;
      readonly record: IssueImportRecord;
      readonly issues: readonly Issue[];
    };

function toRecord(row: typeof issueImports.$inferSelect): IssueImportRecord {
  return {
    orgId: brandId<OrgId>(row.orgId),
    importKey: row.importKey,
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: (JSON.parse(row.issueIds) as string[]).map((id) =>
      brandId<IssueId>(id),
    ),
  };
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toRecord(row) : null;
}

/**
 * Writes the whole batch in one transaction, so a failure part-way leaves
 * nothing behind. The key is re-checked inside the transaction: if another
 * upload with the same key committed first, its record is returned instead.
 */
export async function writeImport(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  importedBy: UserId;
  rows: readonly PreparedImportRow[];
}): Promise<ImportWriteResult> {
  const { orgId, projectId, importKey, importedBy, rows } = input;

  return getDb().transaction((tx) => {
    const existing = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, orgId),
          eq(issueImports.importKey, importKey),
        ),
      )
      .get();
    if (existing) return { replayed: true, record: toRecord(existing) };

    const stamp = toIsoTimestamp(new Date());

    // Resolve label names to this org's labels, creating each missing one once.
    const names = [...new Set(rows.flatMap((row) => row.labelNames))];
    const labelIdByName = new Map<string, LabelId>();
    if (names.length > 0) {
      const found = tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(and(orgPredicate(labels.orgId, orgId), inArray(labels.name, names)))
        .all();
      for (const label of found) {
        labelIdByName.set(label.name, brandId<LabelId>(label.id));
      }
      for (const name of names) {
        if (labelIdByName.has(name)) continue;
        const created = tx
          .insert(labels)
          .values({
            id: newId(),
            orgId,
            name,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .returning({ id: labels.id })
          .get();
        labelIdByName.set(name, brandId<LabelId>(created.id));
      }
    }

    // Archived issues keep their number, so the max spans every row.
    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
      )
      .get();
    let number = highest?.value ?? 0;

    const created: Issue[] = [];
    for (const row of rows) {
      number += 1;
      const inserted = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: importedBy,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = [
        ...new Set(
          row.labelNames.map((name) => labelIdByName.get(name) as LabelId),
        ),
      ];
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }

      created.push(toIssue(inserted, labelIds));
    }

    const record = tx
      .insert(issueImports)
      .values({
        id: newId(),
        orgId,
        importKey,
        projectId,
        importedBy,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return { replayed: false, record: toRecord(record), issues: created };
  });
}
